#!/bin/bash

classpath=$(cat /app/jib-classpath-file)
main_class=$(cat /app/jib-main-class-file)

EXTRA="-Dtenants.mayo.fhir-r4-server-base-url=http://host.docker.internal:8899/mayo/R4"
EXTRA="$EXTRA -Dtenants.mayo.oauth-token-endpoint=http://host.docker.internal:8899/oauth2/token"
EXTRA="$EXTRA -Dtenants.mgb.fhir.r4-url=http://host.docker.internal:8899/mgb/R4"
EXTRA="$EXTRA -Depic.oauth.key."
EXTRA="$EXTRA -Depic.oauth.key."

exec java $JVM_FLAGS $EXTRA -cp "$classpath" "$main_class" "$@"
